use std::fs

fn all_digits(s: string) -> bool {
    if s.len() == 0 {
        return false
    }
    for c in s.chars() {
        if c < '0' || c > '9' {
            return false
        }
    }
    true
}

fn is_leap(y: int) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in_month(y: int, m: int) -> int {
    if m == 2 {
        if is_leap(y) { return 29 }
        return 28
    }
    if m == 4 || m == 6 || m == 9 || m == 11 {
        return 30
    }
    31
}

// returns days since 1970-01-01, or -1000000000 if invalid
fn parse_date(s: string) -> int {
    let bad = -1000000000
    if s.len() != 10 {
        return bad
    }
    let ys = s[0..4]
    let sep1 = s[4..5]
    let ms = s[5..7]
    let sep2 = s[7..8]
    let ds = s[8..10]
    if sep1 != "-" || sep2 != "-" {
        return bad
    }
    if !all_digits(ys) || !all_digits(ms) || !all_digits(ds) {
        return bad
    }
    let y: int = ys.parse::<int>().unwrap_or(0)
    let m: int = ms.parse::<int>().unwrap_or(0)
    let d: int = ds.parse::<int>().unwrap_or(0)
    if m < 1 || m > 12 || d < 1 || d > days_in_month(y, m) {
        return bad
    }
    let yy = if m <= 2 { y - 1 } else { y }
    let era = yy / 400
    let yoe = yy - era * 400
    let mp = (m + 9) % 12
    let doy = (153 * mp + 2) / 5 + d - 1
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy
    era * 146097 + doe - 719468
}

fn main() {
    let names = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"]
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if parts.len() != 2 {
            println("invalid")
            continue
        }
        let a = parse_date(parts[0])
        let b = parse_date(parts[1])
        if a == -1000000000 || b == -1000000000 {
            println("invalid")
            continue
        }
        let lo = if a < b { a } else { b }
        let diff = if a < b { b - a } else { a - b }
        let w = ((lo + 4) % 7 + 7) % 7
        println("${diff} ${names[w as usize]}")
    }
}

